function beginSelectionGesture(e,type,sx=0,sy=0){if(!selection)return;e.preventDefault();e.stopPropagation();const p=point(e),s={...selection};selectionGesture={type,sx,sy,start:p,original:s,pointer:e.pointerId,element:e.currentTarget,startAngle:Math.atan2(p.y-s.y-s.h/2,p.x-s.x-s.w/2)};e.currentTarget.setPointerCapture(e.pointerId)}
